SELECT setseed(0.31);
\copy (WITH cand AS (SELECT u.id::text AS id, u.subject_area, u.question_text AS q, u.option_a oa, u.option_b ob, u.option_c oc, u.option_d od, u.option_e oe, upper(trim(u.correct_answer)) AS key, u.pipeline_metadata::jsonb pm, row_number() OVER (PARTITION BY u.subject_area ORDER BY random()) rn FROM v_safe_for_beta_unfiltered u WHERE u.quality_review_status='unverified' AND u.option_a<>'' AND u.option_e<>'' AND upper(trim(u.correct_answer)) IN ('A','B','C','D','E') AND u.word_count>=8 AND NOT (u.pipeline_metadata::jsonb ? 'demoted_at') AND NOT (u.pipeline_metadata::jsonb ? 'ai_extras' AND (u.pipeline_metadata::jsonb->'ai_extras'->>'topic_match_quality')='fallback') AND NOT (u.id::text IN (SELECT id FROM gate2c_demoted)) AND (NOT (u.pipeline_metadata::jsonb ? 'match_tier') OR (u.pipeline_metadata::jsonb->>'match_tier') <> ALL(ARRAY['tier1_page_inline','tier1b_position_page_inline']))) SELECT id, subject_area, q, oa, ob, oc, od, oe, key FROM cand WHERE rn<=45) TO 'C:/Users/husey/kiro2/backend/scripts/quality/_blindsolve/calib_master.csv' WITH (FORMAT csv, HEADER true);
